WITH latest_stages AS (SELECT symbol, stage FROM scores.stage_snapshots WHERE snapshot_date = (SELECT MAX(snapshot_date) FROM scores.stage_snapshots)), 
three_month_stages AS (SELECT symbol, stage FROM scores.stage_snapshots WHERE snapshot_date >= (CURRENT_DATE - INTERVAL '3 months')) 
SELECT latest_stages.stage, COUNT(*) AS count FROM latest_stages JOIN three_month_stages ON latest_stages.symbol = three_month_stages.symbol GROUP BY latest_stages.stage;
